  }
  private func put(_ from: UnsafeRawBufferPointer) {
      if from.count > 0 { memcpy(room(from.count), from.baseAddress!, from.count) }
  }
  /// The payload written so far, as a copy (no length prefix).
  public var bytes: [UInt8] {
      guard let block = block else { return [] }
      return Array(UnsafeBufferPointer(start: block + 4, count: count))
  }
  public func writeInt(_ v: Int64) {
      var val = v.littleEndian
      memcpy(room(8), &val, 8)
  }
  public func writeInt32(_ v: Int32) {
      var val = v.littleEndian
      memcpy(room(4), &val, 4)
  }
  public func writeDouble(_ v: Double) {
      var val = v.bitPattern.littleEndian
      memcpy(room(8), &val, 8)
  }
  public func writeBool(_ v: Bool) {
      room(1).pointee = v ? 1 : 0
  }
  public func writeByte(_ v: UInt8) {
      room(1).pointee = v
  }
  /// `[4B bodyLen + 4][4B bodyLen][body]`: a record or variant as a map value,
  /// framed the way Dart reads it back.
  public func writeFramed(_ body: (NitroRecordWriter) -> Void) {
      let at = count
      _ = room(8)
      body(self)
      var inner = Int32(count - at - 8).littleEndian
      var outer = Int32(count - at - 4).littleEndian
      memcpy(block! + 4 + at, &outer, 4)
      memcpy(block! + 4 + at + 4, &inner, 4)
  }
  public func writeString(_ v: String) {
      var s = v
      s.withUTF8 { utf8 in
          writeInt32(Int32(utf8.count))
          put(UnsafeRawBufferPointer(utf8))
      }
  }
  public func writeNullTag(_ isNull: Bool) {
      room(1).pointee = isNull ? 0 : 1
  }
  public func writeBlob(_ v: Data) {
      writeInt32(Int32(v.count))
      v.withUnsafeBytes { put($0) }
  }
  /// Raw bytes behind a 4-byte byte count: one copy, for typed arrays.
  public func writeRaw(_ raw: UnsafeRawBufferPointer) {
      writeInt32(Int32(raw.count))
      put(raw)
  }
  /// `[4B count][8B x n]`. The array's storage is the wire form (little-endian
  /// on every Apple target), so the whole list is one copy.
  public func writeIntList(_ v: [Int64]) {
      writeInt32(Int32(v.count))
      v.withUnsafeBytes { put($0) }
  }
  public func writeDoubleList(_ v: [Double]) {
      writeInt32(Int32(v.count))
      v.withUnsafeBytes { put($0) }
  }
  /// `[4B count][1B x n]`: a Bool is stored as the byte 0 or 1, the wire form.
  public func writeBoolList(_ v: [Bool]) {
      writeInt32(Int32(v.count))
      v.withUnsafeBytes { put($0) }
  }
  /// The finished record, `[4B length][payload]`, for Dart to free. Gives up
  /// this writer's block: the writer is empty afterwards.
  public func toNative() -> UnsafeMutablePointer<UInt8>? {
      _ = room(0)
      var length = Int32(count).littleEndian
      memcpy(block!, &length, 4)
      let out = block
      block = nil
      count = 0
      capacity = 0
      return out
  }
  public static func encodeList<T>(_ items: [T], writeItem: (NitroRecordWriter, T) -> Void) -> UnsafeMutablePointer<UInt8>? {
      let w = NitroRecordWriter()
      w.writeInt32(Int32(items.count))
      for item in items { writeItem(w, item) }
      return w.toNative()
  }
  /// Encodes a list of nullable items.
  /// Wire format: [4B count][for each: 1B hasValue][item bytes (only if hasValue)]
  /// Counterpart: NitroRecordReader.decodeNullableList / Dart RecordReader.decodeNullableList.
  public static func encodeNullableList<T>(_ items: [T?], writeItem: (NitroRecordWriter, T) -> Void) -> UnsafeMutablePointer<UInt8>? {
      let w = NitroRecordWriter()
      w.writeInt32(Int32(items.count))
      for item in items {
          w.writeBool(item != nil)
          if let v = item { writeItem(w, v) }
      }
      return w.toNative()
  }
  /// Encodes a list with a per-item byte-offset table for O(1) random access.
  /// Wire format (payload after outer 4B length prefix):
  ///   [int32 count][int64 × count offsets from payload start][item bytes...]
  /// Counterpart: Dart LazyRecordList.decode / RecordWriter.encodeIndexedList.
  public static func encodeIndexedList<T>(_ items: [T], writeItem: (NitroRecordWriter, T) -> Void) -> UnsafeMutablePointer<UInt8>? {
      // One writer: reserve the offset table, write each item straight after
      // it, then fill the table in. (It was a writer and a byte array per item.)
      let w = NitroRecordWriter()
      w.writeInt32(Int32(items.count))
      _ = w.room(8 * items.count)
      for (i, item) in items.enumerated() {
          var offset = Int64(w.count).littleEndian
          memcpy(w.block! + 4 + 4 + 8 * i, &offset, 8)
          writeItem(w, item)
      }
      return w.toNative()
  }
}

public class NitroRecordReader {
  public let bytes: UnsafeMutablePointer<UInt8>
  public var pos: Int = 0
  public init(ptr: UnsafeMutablePointer<UInt8>) {
      self.bytes = ptr.advanced(by: 4)
  }
  public init(payload: UnsafeMutablePointer<UInt8>) {
      self.bytes = payload
  }
  public func readInt() -> Int64 {
      var v: Int64 = 0
      _ = memcpy(&v, bytes.advanced(by: pos), 8)
      pos += 8
      return Int64(littleEndian: v)
  }
  public func readInt32() -> Int32 {
      var v: Int32 = 0
      _ = memcpy(&v, bytes.advanced(by: pos), 4)
      pos += 4
      return Int32(littleEndian: v)
  }
  public func readDouble() -> Double {
      var v: UInt64 = 0
      _ = memcpy(&v, bytes.advanced(by: pos), 8)
      pos += 8
      return Double(bitPattern: UInt64(littleEndian: v))
  }
  public func readBool() -> Bool {
      let v = bytes[pos]
      pos += 1
      return v != 0
  }
  public func readString() -> String {
      let len = Int(readInt32())
      guard len > 0 else { return "" }
      // The standard library's decoder, not Foundation's String(bytes:encoding:):
      // several times faster on short strings (measured), and Dart only sends
      // valid UTF-8.
      let s = String(decoding: UnsafeBufferPointer(start: bytes.advanced(by: pos), count: len), as: UTF8.self)
      pos += len
      return s
  }
  public func readNullTag() -> Bool {
      let v = bytes[pos]
      pos += 1
      return v == 0
  }
  public func readBlob() -> Data {
      let len = Int(readInt32())
      let data = Data(bytes: bytes.advanced(by: pos), count: len)
      pos += len
      return data
  }
  /// [n] fixed-size values copied once into a new array's storage.
  private func readValues<T>(_ n: Int, of type: T.Type) -> [T] {
      let byteCount = n * MemoryLayout<T>.stride
      let out = [T](unsafeUninitializedCapacity: n) { buffer, count in
          if n > 0 { memcpy(buffer.baseAddress!, bytes.advanced(by: pos), byteCount) }
          count = n
      }
      pos += byteCount
      return out
  }
  /// A typed array field: `[4B byteCount][bytes]`.
  public func readArray<T>(of type: T.Type) -> [T] {
      return readValues(Int(readInt32()) / MemoryLayout<T>.stride, of: type)
  }
  /// `[4B count][8B x n]`.
  public func readIntList() -> [Int64] { return readValues(Int(readInt32()), of: Int64.self) }
  public func readDoubleList() -> [Double] { return readValues(Int(readInt32()), of: Double.self) }
  /// `[4B count][1B x n]`. Each byte is compared, not reinterpreted: a Bool
  /// holding anything but 0 or 1 is undefined behaviour.
  public func readBoolList() -> [Bool] {
      let n = Int(readInt32())
      let from = bytes.advanced(by: pos)
      pos += n
      return [Bool](unsafeUninitializedCapacity: n) { buffer, count in
          for i in 0..<n { buffer[i] = from[i] != 0 }
          count = n
      }
  }
  public func readBlobAsPointer() -> UnsafeMutablePointer<UInt8>? {
      let len = Int(readInt32())
      if (len == 0) { return nil }
      let ptr = UnsafeMutablePointer<UInt8>.allocate(capacity: len)
      ptr.initialize(from: bytes.advanced(by: pos), count: len)
      pos += len
      return ptr
  }
  public static func decodeList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      var items: [T] = []
      for _ in 0..<count {
          items.append(readItem(r))
      }
      return items
  }
  /// Decodes a list of nullable items.
  /// Wire format: [4B count][for each: 1B hasValue][item bytes (only if hasValue)]
  /// Counterpart: NitroRecordWriter.encodeNullableList / Dart RecordWriter.encodeNullableList.
  public static func decodeNullableList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T?] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      var items: [T?] = []
      for _ in 0..<count {
          let hasValue = r.readBool()
          items.append(hasValue ? readItem(r) : nil)
      }
      return items
  }
  /// Decodes a list encoded by Dart's RecordWriter.encodeIndexedList / encodeIndexedPrimitiveList.
  /// Wire format (payload after outer 4B length prefix):
  ///   [int32 count][int64 × count offsets from payload start][item bytes...]
  /// The offset table is skipped; items are read sequentially after it.
  public static func decodeIndexedList<T>(_ ptr: UnsafeMutablePointer<UInt8>, readItem: (NitroRecordReader) -> T) -> [T] {
      let r = NitroRecordReader(ptr: ptr)
      let count = r.readInt32()
      r.pos += Int(count) * 8  // skip Int64 offset table
      var items: [T] = []
      for _ in 0..<count {
          items.append(readItem(r))
      }
      return items
  }
}

/**
 * Protocol for the NitroServerNative module (NativeImpl.cpp).
 * Conform to this in your Swift/ObjC++ source code if you want
 * to delegate from the C++ HybridObject to a Swift implementation.
 * Nitro may call this implementation from any native thread.
 * Keep mutable state thread-safe or marshal work onto your own queue/actor.
 */
public protocol HybridNitroServerNativeProtocol: AnyObject {
    func engineVersion() -> String
    func supportsTls() -> Bool
    func resetNative() -> Void
    func supportsBrotli() -> Bool
    func brotliEncode(data: Data, quality: Int64) -> Data
    func brotliDecode(data: Data) -> Data
    func jsonCreate() -> Any
    func jsonFree(writer: Any) -> Void
    func jsonAlloc(bytes: Int64) -> Any
    func jsonFreeBuffer(buffer: Any) -> Void
    func jsonReset(writer: Any) -> Void
    func jsonBeginObject(writer: Any) -> Void
    func jsonEndObject(writer: Any) -> Void
    func jsonBeginArray(writer: Any) -> Void
    func jsonEndArray(writer: Any) -> Void
    func jsonKey(writer: Any, bytes: Any, length: Int64) -> Void
    func jsonInt(writer: Any, value: Int64) -> Void
    func jsonDouble(writer: Any, value: Double) -> Void
    func jsonString(writer: Any, bytes: Any, length: Int64) -> Void
    func jsonBool(writer: Any, value: Bool) -> Void
    func jsonNull(writer: Any) -> Void
    func jsonRaw(writer: Any, bytes: Any, length: Int64) -> Void
    func jsonEmitTemplate(writer: Any, records: Int64, columns: Int64, segments: Any, segmentLengths: Any, columnTypes: Any, columnData: Any) -> Void
    func jsonBytes(writer: Any) -> Any
    func jsonLength(writer: Any) -> Int64
    func configureServer(config: RawServerConfig) -> Void
    func reloadTls(tls: RawTlsConfig) -> Bool
    func registerRoute(route: RawRouteConfig) -> RawServerStatus
    func unregisterRoute(method: String, pattern: String) -> RawServerStatus
    func registerStaticRoute(method: String, pattern: String, status: Int64, headers: [RawHeader], body: Data) -> RawServerStatus
    func start() -> RawServerStatus
    func stop() -> Void
    func beginDrain() -> Void
    func inFlightRequests() -> Int64
    func liveConnections() -> Int64
    func emitterId() -> Int64
    func detachEmitter(id: Int64) -> Bool
    func respondFile(requestId: Int64, status: Int64, headers: [RawHeader], path: String, offset: Int64, length: Int64) -> Void
    func respond(requestId: Int64, status: Int64, headers: [RawHeader], body: Data) -> Void
    func ackBody(requestId: Int64, ackedChunks: Int64) -> Void
    func startStream(requestId: Int64, status: Int64, headers: [RawHeader]) -> Void
    func sendStreamChunk(requestId: Int64, chunk: Data, last: Bool) -> Void
    func wsSend(connectionId: Int64, payload: Data, binary: Bool, compressed: Bool) -> Int64
    func wsClose(connectionId: Int64, code: Int64) -> Void
    var incomingRequests: AnyPublisher<RawIncomingRequest, Never> { get }
    var bodyChunks: AnyPublisher<RawBodyChunk, Never> { get }
    var serverEvents: AnyPublisher<RawServerEvent, Never> { get }
    var wsMessages: AnyPublisher<RawWsMessage, Never> { get }
}

public class NitroServerNativeRegistry {
    public static var impl: HybridNitroServerNativeProtocol?

    public static func register(_ impl: HybridNitroServerNativeProtocol) {
        NitroServerNativeRegistry.impl = impl
    }

    // Stream: incomingRequests cancellables keyed by dartPort
    public static var _incomingRequestsCancellables = [Int64: AnyCancellable]()

    // Stream: bodyChunks cancellables keyed by dartPort
    public static var _bodyChunksCancellables = [Int64: AnyCancellable]()

    // Stream: serverEvents cancellables keyed by dartPort
    public static var _serverEventsCancellables = [Int64: AnyCancellable]()

    // Stream: wsMessages cancellables keyed by dartPort
    public static var _wsMessagesCancellables = [Int64: AnyCancellable]()
}

// NOTE: @_cdecl bridge stubs are NOT generated for NativeImpl.cpp modules.
// The .bridge.g.mm C++ shim calls nitro_server_xxx() C functions directly.
